package au.edu.uow.csci318.activity.application;import au.edu.uow.csci318.activity.domain.StudySession;import au.edu.uow.csci318.activity.infrastructure.StudySessionRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.cloud.stream.function.StreamBridge;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.RestClient;import java.time.*;import java.time.temporal.TemporalAdjusters;import java.util.*;
@Service public class StudyActivityApplicationService{private final StudySessionRepository repo;private final StreamBridge events;private final RestClient subjects;public StudyActivityApplicationService(StudySessionRepository r,StreamBridge e,RestClient.Builder b,@Value("${services.subject-url}")String url){repo=r;events=e;subjects=b.baseUrl(url).build();}
 @Transactional public Response record(CreateRequest r){verify(r.subjectId());var s=repo.save(new StudySession(r.subjectId(),r.durationMinutes(),r.studyDate(),r.description()));var response=response(s);events.send("studyActivityEvents-out-0",new Envelope(UUID.randomUUID(),"StudySessionRecorded",1,Instant.now(),"study-activity-service",response));return response;}
 public List<Response>all(){return repo.findAll().stream().map(this::response).toList();}public Summary summary(UUID subjectId,LocalDate weekOf){LocalDate from=(weekOf==null?LocalDate.now():weekOf).with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));LocalDate to=from.plusDays(6);var sessions=repo.findBySubjectIdAndStudyDateBetween(subjectId,from,to);return new Summary(subjectId,from,to,sessions.stream().mapToInt(StudySession::getDurationMinutes).sum(),sessions.size());}
 private void verify(UUID id){try{subjects.get().uri("/api/subjects/{id}",id).retrieve().toBodilessEntity();}catch(Exception e){throw new DependencyException("Referenced subject does not exist or Subject Service is unavailable",e);}}private Response response(StudySession s){return new Response(s.getId(),s.getSubjectId(),s.getDurationMinutes(),s.getStudyDate(),s.getDescription(),s.getRecordedAt());}
 public record CreateRequest(UUID subjectId,int durationMinutes,LocalDate studyDate,String description){}public record Response(UUID id,UUID subjectId,int durationMinutes,LocalDate studyDate,String description,Instant recordedAt){}public record Summary(UUID subjectId,LocalDate weekStart,LocalDate weekEnd,int totalMinutes,int sessionCount){}public record Envelope(UUID eventId,String eventType,int eventVersion,Instant eventTimestamp,String sourceService,Object payload){}public static class DependencyException extends RuntimeException{public DependencyException(String m,Throwable c){super(m,c);}}
}
